{"command": "cat > /tmp/create_json.py << 'EOF'
import json

# Read the kernels
with open('/tmp/corrected_kernels.py', 'r') as f:
    kernel_code = f.read()

# Extract just the kernel functions (without imports)
lines = kernel_code.split('\n')
greedy_kernel = []
random_kernel = []
current_kernel = None

for line in lines:
    if line.startswith('@triton.jit'):
        if 'rejection_greedy_sample_kernel' in line:
            current_kernel = 'greedy'
            greedy_kernel.append(line)
        elif 'rejection_random_sample_kernel' in line:
            current_kernel = 'random'
            random_kernel.append(line)
        else:
            current_kernel = None
    elif current_kernel == 'greedy':
        greedy_kernel.append(line)
    elif current_kernel == 'random':
        random_kernel.append(line)

greedy_kernel_str = '\n'.join(greedy_kernel)
random_kernel_str = '\n'.join(random_kernel)

# Create JSON output
output = {
    "vllm/v1/sample/rejection_sampler.py": {
        "rejection_greedy_sample_kernel": greedy_kernel_str,
        "rejection_random_sample_kernel": random_kernel_str
    }
}

print(json.dumps(output, indent=2))
EOF
python3 /tmp/create_json.py > /tmp/prediction.json
cat /tmp/prediction.json"}

