{
    "vllm/v1/sample/rejection_sampler.py": {
        "rejection_greedy_sample_kernel": "@triton.jit(do_not_specialize=[\"max_spec_len\"])\ndef rejection_greedy_sample_kernel(\n    output_token_ids_ptr,  # [batch_size, max_spec_len + 1]\n    cu_num_draft_tokens_ptr,  # [batch_size]\n    draft_token_ids_ptr,  # [num_tokens]\n    target_argmax_ptr,  # [num_tokens]\n    bonus_token_ids_ptr,  # [batch_size]\n    is_greedy_ptr,  # [batch_size] or None\n    max_spec_len,\n):\n    \"\"\"\n    Performs rejection sampling for greedy sampling requests.\n    \n    For each request:\n    1. Compare draft tokens with target argmax tokens\n    2. Accept while they match\n    3. Stop at first mismatch, use target argmax token at that position\n    4. If all tokens match, add bonus token at position num_draft_tokens\n    \"\"\"\n    req_idx = tl.program_id(0)\n    \n    # Get start and end indices for this request\n    if req_idx == 0:\n        start_idx = 0\n    else:\n        start_idx = tl.load(cu_num_draft_tokens_ptr + req_idx - 1)\n    end_idx = tl.load(cu_num_draft_tokens_ptr + req_idx)\n    num_draft_tokens = end_idx - start_idx\n    \n    # Check if this request is greedy\n    # If is_greedy_ptr is None (all requests are greedy), treat as greedy\n    is_greedy = True\n    if is_greedy_ptr is not None:\n        is_greedy = tl.load(is_greedy_ptr + req_idx)\n    \n    # Only process greedy requests\n    if not is_greedy:\n        return\n    \n    # Get bonus token for this request\n    bonus_token_id = tl.load(bonus_token_ids_ptr + req_idx)\n    \n    # Initialize all accepted flag\n    all_accepted = True\n    \n    # Process each draft token position\n    pos = 0\n    while pos < num_draft_tokens:\n        # Get draft token and target argmax token\n        draft_token = tl.load(draft_token_ids_ptr + start_idx + pos)\n        target_token = tl.load(target_argmax_ptr + start_idx + pos)\n        \n        if draft_token == target_token:\n            # Accept draft token\n            tl.store(output_token_ids_ptr + req_idx * (max_spec_len + 1) + pos, draft_token)\n            pos += 1\n        else:\n            # Reject: use target token at this position\n            tl.store(output_token_ids_ptr + req_idx * (max_spec_len + 1) + pos, target_token)\n            all_accepted = False\n            # Stop processing further positions for this request\n            break\n    \n    # If all tokens were accepted, add bonus token at position num_draft_tokens\n    if all_accepted and num_draft_tokens > 0:\n        tl.store(output_token_ids_ptr + req_idx * (max_spec_len + 1) + num_draft_tokens, bonus_token_id)",
        "rejection_random_sample_kernel": "@triton.jit(do_not_specialize=[\"max_spec_len\"])\ndef rejection_random_sample_kernel(\n    output_token_ids_ptr,  # [batch_size, max_spec_len + 1]\n    cu_num_draft_tokens_ptr,  # [batch_size]\n    draft_token_ids_ptr,  # [num_tokens]\n    draft_probs_ptr,  # [num_tokens, vocab_size] or None\n    target_probs_ptr,  # [num_tokens, vocab_size]\n    bonus_token_ids_ptr,  # [batch_size]\n    recovered_token_ids_ptr,  # [num_tokens]\n    uniform_probs_ptr,  # [num_tokens]\n    is_greedy_ptr,  # [batch_size]\n    max_spec_len,\n    vocab_size,\n    IS_NGRAM: tl.constexpr,\n):\n    \"\"\"\n    Performs rejection sampling for random sampling requests.\n    \n    For each request:\n    1. For each position, compare uniform random number with acceptance probability\n    2. If accepted, use draft token\n    3. If rejected, use recovered token\n    4. If all tokens accepted, add bonus token at position num_draft_tokens\n    \"\"\"\n    req_idx = tl.program_id(0)\n    \n    # Get start and end indices for this request\n    if req_idx == 0:\n        start_idx = 0\n    else:\n        start_idx = tl.load(cu_num_draft_tokens_ptr + req_idx - 1)\n    end_idx = tl.load(cu_num_draft_tokens_ptr + req_idx)\n    num_draft_tokens = end_idx - start_idx\n    \n    # Check if this request is greedy (skip if greedy)\n    is_greedy = tl.load(is_greedy_ptr + req_idx)\n    if is_greedy:\n        return\n    \n    # Get bonus token for this request\n    bonus_token_id = tl.load(bonus_token_ids_ptr + req_idx)\n    \n    # Initialize all accepted flag\n    all_accepted = True\n    \n    # Process each draft token position\n    pos = 0\n    while pos < num_draft_tokens:\n        # Get uniform random probability for this position\n        uniform_prob = tl.load(uniform_probs_ptr + start_idx + pos)\n        \n        # Get draft token ID\n        draft_token_id = tl.load(draft_token_ids_ptr + start_idx + pos)\n        \n        # Get draft probability for this token\n        if IS_NGRAM:\n            # For N-gram, draft probability is considered as 1\n            draft_prob = 1.0\n        else:\n            draft_prob = tl.load(draft_probs_ptr + (start_idx + pos) * vocab_size + draft_token_id)\n        \n        # Get target probability for this token\n        target_prob = tl.load(target_probs_ptr + (start_idx + pos) * vocab_size + draft_token_id)\n        \n        # Acceptance probability: min(1, target_prob / draft_prob)\n        # Avoid division by zero\n        acceptance_prob = tl.minimum(1.0, target_prob / tl.maximum(draft_prob, 1e-10))\n        \n        if uniform_prob < acceptance_prob:\n            # Accept draft token\n            tl.store(output_token_ids_ptr + req_idx * (max_spec_len + 1) + pos, draft_token_id)\n            pos += 1\n        else:\n            # Reject: use recovered token\n            recovered_token_id = tl.load(recovered_token_ids_ptr + start_idx + pos)\n            tl.store(output_token_ids_ptr + req_idx * (max_spec_len + 1) + pos, recovered_token_id)\n            all_accepted = False\n            # Stop processing further positions for this request\n            break\n    \n    # If all tokens were accepted, add bonus token at position num_draft_tokens\n    if all_accepted and num_draft_tokens > 0:\n        tl.store(output_token_ids_ptr + req_idx * (max_spec_len + 1) + num_draft_tokens, bonus_token_id)"
    }
}
